package com.kjalumni.announcement.entity;
import com.kjalumni.auth.entity.User; import com.kjalumni.common.entity.BaseEntity; import com.kjalumni.common.enums.*; import jakarta.persistence.*; import lombok.*; import java.util.UUID;
@Entity @Table(name="announcements") @Getter @Setter @Builder @NoArgsConstructor @AllArgsConstructor public class Announcement extends BaseEntity { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @Column(nullable=false,length=180) private String title; @Column(nullable=false,columnDefinition="TEXT") private String message; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private EventVisibility visibility; @Enumerated(EnumType.STRING) @Column(length=20) private Branch branch; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private AnnouncementPriority priority; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private AnnouncementStatus status; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="created_by",nullable=false) private User createdBy; }
